void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec3 col = vec3(iChannelResolution[0].xy / 512.0, iChannelResolution[0].z);
  col.b *= 0.5;
  col += vec3(iChannelTime[0], iChannelTime[1], 0.0);
  fragColor = vec4(col * (0.5 + 0.5 * uv.x), 1.0);
}
